test('held Stripe sandbox verifies ACH ownership and applies one invoice payment at 1440 and 390',async({page})=>{
  test.skip(process.env.PIER_STRIPE_LIVE!=='1','Run explicitly with the held US Stripe sandbox key.');
  if(!process.env.PIER_STRIPE_SECRET)throw new Error('The live ACH journey requires the held Stripe sandbox key.');
  test.setTimeout(240000);
  // @ts-expect-error Shared live-provider browser journey, invoked only explicitly.
  const {exerciseLiveAch}=await import('./ach-live.mjs');await exerciseLiveAch(page,expect,shots);
});
